<?php
require_once __DIR__.'/import_action_template.php';

function impReconciliationLayout($subject,$title,$subtitle,$body,$url,$button,$client=false,$english=false) {
    $e='impActionEscape';$signature=$client?'<img src="cid:imporlan-signature-jp" width="280" alt="Juan Pablo · Imporlan" style="display:block;max-width:100%;height:auto;margin-top:24px">':'<p style="margin-top:24px;color:#526b78;font-size:13px">Imporlan · Operaciones</p>';
    return '<!doctype html><html lang="'.($english?'en':'es').'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$e($subject).'</title><style>@media(max-width:620px){.outer{padding:12px 8px!important}.pad{padding:24px 20px!important}h1{font-size:28px!important}.cta{display:block!important;text-align:center!important}}</style></head><body style="margin:0;background:#edf3f5;font-family:Arial,Helvetica,sans-serif;color:#102f3d"><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td class="outer" align="center" style="padding:28px 12px"><table role="presentation" cellspacing="0" cellpadding="0" style="width:100%;max-width:600px;background:#fff;border:1px solid #dce7eb;border-radius:18px;overflow:hidden"><tr><td class="pad" style="padding:28px 32px;background:#102f3d;border-bottom:5px solid #2cb6c2"><p style="margin:0;color:#fff;font-size:29px;font-weight:bold;letter-spacing:4px">IMPORLAN<span style="color:#2cb6c2">.</span></p><p style="color:#b8d4dc;font-size:12px">'.$e($subtitle).'</p></td></tr><tr><td class="pad" style="padding:30px 32px"><h1 style="font-size:34px;line-height:1.15;margin:0 0 22px">'.$e($title).'</h1>'.$body.'<a class="cta" href="'.$e($url).'" style="display:inline-block;margin-top:22px;background:#087e91;color:white;font-weight:bold;text-decoration:none;border-radius:8px;padding:15px 22px">'.$e($button).' &rarr;</a>'.$signature.'<p style="margin-top:20px;font-size:12px;color:#526b78">'.$e($english?'Open your private portal to see the current instructions. This notice does not record a purchase.':'Este aviso confirma los ingresos registrados. Los avances de compra e importación se registran por separado.').'</p></td></tr></table></td></tr></table></body></html>';
}
function impReconciliationFinancialEmail($c,$audience) {
    $e='impActionEscape';$client=$audience==='client';$order=$c['order'];$r=$c['request'];$n=$c['number'];$total=intval($r['amount_clp']);$subject='Cuadre listo · Pago '.$n.' · '.$order['order_number'];$url='https://www.imporlan.cl/panel/'.($client?'#/payments?'.($c['evidence']['missing_proofs']>0?'comprobante':'pagar').'='.rawurlencode($r['id']):'admin/#/orders?id='.intval($order['id']));
    $missing=$c['evidence']['missing_proofs'];$review=$c['evidence']['review_pending'];
    $intro=$client?'Hola '.trim(explode(' ',$order['customer_name'])[0]).', ya confirmé los ingresos que cubren este pago. No tienes que volver a pagarlo.':'El total de esta cuota está cubierto por ingresos confirmados. Revisa los respaldos y el siguiente paso de la operación.';
    $proof=$missing||$review?'Documentación por completar: '.$missing.' comprobante(s) faltante(s) y '.$review.' por revisar. El ingreso ya está registrado; adjuntar el respaldo no genera otro cobro.':'Los respaldos de esta cuota están revisados.';
    $purchase=$n===2 && opuHitoEnCurso($order)==='compra' && !impPurchaseClearanceFor(getDbConnection(),$order)['ready']?'La compra continúa en espera de la conciliación documental y la autorización de Imporlan.':'El registro de ingresos de esta cuota está actualizado. Revisa el avance de la operación en tu panel.';
    $body='<p style="font-size:15px;line-height:1.8">'.$e($intro).'</p><div style="padding:22px;background:#f0fbfc;border:1px solid #a8d9df;border-radius:12px"><p style="color:#167450;font-weight:bold;margin-top:0">Pago '.$n.' completo · saldo de esta cuota: $0 CLP</p><table role="presentation" width="100%" style="font-size:14px;line-height:2"><tr><td>Total de la cuota</td><td align="right">'.$e(impActionMoney($total)).'</td></tr><tr><td>Ingresos confirmados</td><td align="right"><strong>'.$e(impActionMoney($c['confirmed'])).'</strong></td></tr><tr><td>Saldo por pagar</td><td align="right">$0 CLP</td></tr></table></div><p style="font-size:14px;line-height:1.8">'.$e($proof).'</p><p style="font-size:14px;line-height:1.8">'.$e($purchase).'</p>';
    $excess=$c['confirmed']>$total?'Excedente registrado: '.impActionMoney($c['confirmed']-$total).'. El equipo revisará su aplicación; no se descuenta automáticamente de otra cuota.':'';
    if($excess!=='')$body.='<p style="font-size:14px">'.$e($excess).'</p>';
    $text=$subject."\n\n".$intro."\n\nTotal de la cuota: ".impActionMoney($total)."\nIngresos confirmados: ".impActionMoney($c['confirmed'])."\nSaldo por pagar: $0 CLP\n\n".$proof."\n\n".$purchase."\n\n".$url."\n\nJuan Pablo · Imporlan\ncontacto@imporlan.cl";
    return ['subject'=>$subject,'html'=>impReconciliationLayout($subject,'Cuadre de ingresos listo','Pago '.$n.' · '.$order['order_number'],$body,$url,$client?'Ver pago y comprobantes':'Revisar cuadre',$client),'text'=>$text.($excess!==''?"\n\n".$excess:'')];
}
function impReconciliationCoordinatorEmail($d) {
    $subject='[Imporlan] Client installment completed · '.$d['order_number'];
    $message=empty($d['purchase_hold'])?'The client installment is complete. Follow the current instructions in your private portal. This notice does not authorize a new purchase.':'The client installment is complete. The Imporlan team is finishing the internal review. Please wait for the authorization in your private portal before committing funds or purchasing the boat.';
    if(!empty($d['start_operation']))$message='The first client installment is complete and the operation is confirmed. Please proceed with the availability checks and inspection coordination requested in your private portal. This does not authorize purchasing the boat yet.';
    $body='<p style="font-size:15px;line-height:1.8">'.impActionEscape($message).'</p>';
    return ['subject'=>$subject,'html'=>impReconciliationLayout($subject,'Client installment completed',$d['order_number'],$body,$d['portal'],'Open private portal',false,true),'text'=>$subject."\n\n".$message."\n\n".$d['portal']];
}
